    'install.sub': 'Get going',
    'vibe.eyebrow': 'Vibe-chill install',
    'vibe.title': 'Why touch a terminal<br/>when you have <em>Claude Code</em>?',
    'vibe.intro': 'Paste this one prompt into your Claude Code session. Say "y" when it asks for permission. Done.',
    'vibe.bonus': 'No git, no jq install dance, no <code class="mono">settings.json</code> hunt — Claude handles every step and asks before each command.',
    'vibe.panel.label': 'paste in Claude Code:',
    'vibe.prompt': 'Install claude-code-statusline by amazopic for me. First make sure jq is installed (run `which jq`) — if missing, install it for the platform: `sudo apt-get install -y jq` (Ubuntu/Debian), `sudo dnf install -y jq` (Fedora), `brew install jq` (macOS), `sudo apk add jq` (Alpine). Then read ~/.claude/settings.json — if it has a statusLine.command pointing to an existing file (e.g. ~/.claude/status-line.sh or another path), back up that file by appending .bak (overwrite any existing .bak). Also if ~/.claude/status-line.sh already exists, back it up the same way. Then clone github.com/amazopic/claude-code-statusline, copy statusline-bundle.sh to ~/.claude/status-line.sh and make it executable, also copy commands/statusline.md to ~/.claude/commands/. Update ~/.claude/settings.json so statusLine is { type: "command", command: "<absolute path to ~/.claude/status-line.sh>" }. Finally run ~/.claude/status-line.sh use developer to test the developer theme and tell me to restart Claude Code.',
    'vibe.note': '↳ Just say <code class="mono">y</code> (yes) at every permission prompt — Claude will run each command one by one.',
    'install.title': 'Install in 30 seconds',
    'install.intro': 'A single bundled script does both jobs: it renders your status line when Claude Code calls it, and it acts as a CLI configurator when you call it with arguments.',
    'install.step1.title': 'Clone &amp; copy',
    'install.step1.desc': 'Drop the bundle into <code class="mono">~/.claude/status-line.sh</code>.',
    'install.step2.title': 'Pick a theme',
    'install.step2.desc': 'Or compose blocks via <code class="mono">custom</code>.',
    'install.step3.title': 'Wire it up',
    'install.step3.desc': 'Tell Claude Code about it in <code class="mono">settings.json</code>, restart.',
    'install.claude.label': 'Or in Claude Code — easiest',
    'install.claude.intro': 'Have Claude Code open? Paste these two prompts and you\'re done — no terminal needed.',
    'install.claude.prompt1': 'Install claude-code-statusline by amazopic for me. First make sure jq is installed (run `which jq`) — if missing, install it for the platform: `sudo apt-get install -y jq` (Ubuntu/Debian), `sudo dnf install -y jq` (Fedora), `brew install jq` (macOS), `sudo apk add jq` (Alpine). Then read ~/.claude/settings.json — if it has a statusLine.command pointing to an existing file (e.g. ~/.claude/status-line.sh or another path), back up that file by appending .bak (overwrite any existing .bak). Also if ~/.claude/status-line.sh already exists, back it up the same way. Then clone github.com/amazopic/claude-code-statusline, copy statusline-bundle.sh to ~/.claude/status-line.sh and make it executable, also copy commands/statusline.md to ~/.claude/commands/. Update ~/.claude/settings.json so statusLine is { type: "command", command: "<absolute path to ~/.claude/status-line.sh>" }. Finally run ~/.claude/status-line.sh use developer to test the developer theme and tell me to restart Claude Code.',
    'install.claude.prompt2_label': 'Then test it:',
