    'hero.context.tip_clear': '⚠ À vider bientôt — la qualité chute au-dessus de 60%.',
    'hero.context.tip_compact': '🚨 Compactez maintenant — limites qui brûlent.',
    'hero.context.tip_critical': '🚨 Critique — chaque réponse gaspille des tokens.',
    'hero.context.tip_compacted': '✓ Compacté — vif à nouveau.',
    'hero.cta.install': 'Installer en 30s',
