    'specimens.try.caption': 'Un script, deux modes — <strong>stdin = rendu</strong>, <strong>args = config</strong>. Déjà livré comme <code class="mono">~/.claude/commands/statusline.md</code>.',

    'compare.sub': 'Côte à côte',
