    'recipe.title': 'Composez<br/>la vôtre',
    'recipe.intro': 'Cliquez sur les blocs pour les ajouter. Voyez le rendu en direct. Copiez le bash et déployez.',
    'recipe.palette.h': 'Blocs disponibles',
    'recipe.preview': 'Aperçu live',
