    'vibe.eyebrow': 'Vibe-chill namestitev',
    'vibe.title': 'Zakaj sam,<br/>ko imaš <em>Claude Code</em>?',
    'vibe.intro': 'Prilepi ta en poziv v sejo Claude Code. Reci „y" ko vpraša za dovoljenje. Končano.',
    'vibe.bonus': 'Brez git, brez jq install plesov, brez iskanja po <code class="mono">settings.json</code> — Claude opravi vsak korak in vpraša pred vsakim ukazom.',
    'vibe.panel.label': 'prilepi v Claude Code:',
    'vibe.prompt': 'Namesti claude-code-statusline od amazopic zame. Najprej preveri da je jq nameščen (zaženi `which jq`) — če ga ni, ga namesti glede na platformo: `sudo apt-get install -y jq` (Ubuntu/Debian), `sudo dnf install -y jq` (Fedora), `brew install jq` (macOS), `sudo apk add jq` (Alpine). Nato preberi ~/.claude/settings.json — če je tam statusLine.command, ki kaže na obstoječo datoteko (npr. ~/.claude/status-line.sh ali drugo pot), naredi varnostno kopijo te datoteke z dodatkom .bak (prepiši obstoječo .bak). Tudi če ~/.claude/status-line.sh že obstaja — naredi varnostno kopijo enako. Nato kloniraj github.com/amazopic/claude-code-statusline, kopiraj statusline-bundle.sh v ~/.claude/status-line.sh in ga naredi izvršljivega, kopiraj tudi commands/statusline.md v ~/.claude/commands/. Posodobi ~/.claude/settings.json tako da statusLine = { type: "command", command: "<absolutna pot do ~/.claude/status-line.sh>" }. Na koncu zaženi ~/.claude/status-line.sh use developer za test teme developer in mi reci da ponovno zaženem Claude Code.',
    'vibe.note': '↳ Samo reci <code class="mono">y</code> (ja) ob vsaki zahtevi za dovoljenje — Claude bo izvajal ukaze enega za drugim.',
    'install.title': 'Namestitev v 30 sekundah',
    'install.intro': 'En sam bundle skript opravlja oboje: izriše vašo vrstico stanja, ko jo Claude Code pokliče, in deluje kot CLI konfigurator, ko ga pokličete z argumenti.',
    'install.step1.title': 'Kloniraj in kopiraj',
    'install.step1.desc': 'Postavite bundle v <code class="mono">~/.claude/status-line.sh</code>.',
    'install.step2.title': 'Izberi temo',
    'install.step2.desc': 'Ali sestavite bloke prek <code class="mono">custom</code>.',
    'install.step3.title': 'Poveži',
    'install.step3.desc': 'Povejte Claude Code v <code class="mono">settings.json</code>, znova zaženite.',
    'install.claude.label': 'Ali v Claude Code — najlažje',
    'install.claude.intro': 'Claude Code že odprt? Prilepite ta dva poziva — končano, terminal ni potreben.',
    'install.claude.prompt1': 'Namesti claude-code-statusline od amazopic zame. Najprej preveri da je jq nameščen (zaženi `which jq`) — če ga ni, ga namesti glede na platformo: `sudo apt-get install -y jq` (Ubuntu/Debian), `sudo dnf install -y jq` (Fedora), `brew install jq` (macOS), `sudo apk add jq` (Alpine). Nato preberi ~/.claude/settings.json — če je tam statusLine.command, ki kaže na obstoječo datoteko (npr. ~/.claude/status-line.sh ali drugo pot), naredi varnostno kopijo te datoteke z dodatkom .bak (prepiši obstoječo .bak). Tudi če ~/.claude/status-line.sh že obstaja — naredi varnostno kopijo enako. Nato kloniraj github.com/amazopic/claude-code-statusline, kopiraj statusline-bundle.sh v ~/.claude/status-line.sh in ga naredi izvršljivega, kopiraj tudi commands/statusline.md v ~/.claude/commands/. Posodobi ~/.claude/settings.json tako da statusLine = { type: "command", command: "<absolutna pot do ~/.claude/status-line.sh>" }. Na koncu zaženi ~/.claude/status-line.sh use developer za test teme developer in mi reci da ponovno zaženem Claude Code.',
    'install.claude.prompt2_label': 'Potem preizkusi:',
    'install.codelabel.main': 'macOS / Linux / WSL',
    'install.codelabel.slash': 'Neobvezno: ukaz <code class="mono">/statusline</code>',
    'faq.sub': 'V &amp; O',
    'faq.title': 'Pogosta<br/>vprašanja',
    'faq.q.limits': 'Zakaj je prikaz 5h / 7d omejitev glavna funkcija?',
    'faq.a.limits': 'Ker je to pritožba št. 1 po nakupu Claude naročnine: privzeta vrstica daje <strong>ničelno vidljivost</strong> v vaše 5-urne in 7-dnevne omejitve. Skript bere podatke <code>limits</code>, izriše oba merilnika v živo in sproži ⚠️ vizualni alarm nad 50 %.',
    'faq.q.what': 'Kaj je »Claude Code Status Line«?',
    'faq.a.what': 'Bash zamenjava privzete vrstice stanja v <a href="https://claude.com/claude-code">Claude Code</a>. Spodnjo vrstico spremeni v pravo armaturno ploščo: model, % konteksta, vrstica napredka, stroški seje, <strong>5h / 7d omejitve</strong>, git status, čas naloge in več.',
    'faq.q.install': 'Kako se namesti?',
    'faq.a.install': 'Kopirajte <code>statusline-bundle.sh</code> v <code>~/.claude/status-line.sh</code>, naredite <code>chmod +x</code>, nato usmerite <code>~/.claude/settings.json</code> na to pot.',
    'faq.q.update': 'Kako posodobim na najnovejšo različico?',
    'faq.a.update': 'Zaženite <code>~/.claude/status-line.sh update</code>. Ukaz prenese najnovejši bundle z GitHub, ustvari varnostno kopijo s časovnim žigom (<code>~/.claude/status-line.sh.bak.&lt;YYYYMMDD-HHMMSS&gt;</code>) in ohrani vašo konfiguracijo teme. Nato znova zaženite Claude Code. Preverite nameščeno različico: <code>~/.claude/status-line.sh version</code>.',
    'faq.q.1m': 'Podpira 1M kontekstne modele?',
    'faq.a.1m': 'Da. Skript zazna <code>[1m]</code> v ID modela in <code>1M</code> v imenu, prilagodi imenovalec na 1.000.000 žetonov.',
    'faq.q.models': 'S katerimi modeli deluje?',
    'faq.a.models': 'Z vsakim modelom, ki ga podpira Claude Code — Opus 4.7, Sonnet 4.6, Haiku 4.5, Opus 4.6 itd.',
    'faq.q.customize': 'Lahko prilagodim barve, teme, dodam svoje?',
    'faq.a.customize': 'Da — trije načini: izberite eno od 158 различic, sestavite svojo iz blokov, ali urejajte <code>statusline.sh</code> neposredno.',
    'faq.q.perf': 'Bo upočasnil Claude Code?',
    'faq.a.perf': 'Ne. Tipičen rendering ≤ 50 ms tudi s sledilnikom časa.',
    'faq.q.jq': 'Deluje brez jq?',
    'faq.a.jq': '<code>jq</code> je obvezen — parsa JSON, ki ga pošlje Claude Code.',
    'faq.q.win': 'Deluje v Windows?',
    'faq.a.win': 'Da, v vsakem okolju z <code>bash</code> 4+ in <code>jq</code> — Git Bash, WSL, MSYS2, Cygwin.',
    'faq.q.conf': 'Kje je shranjena konfiguracija?',
    'faq.a.conf': '<code>~/.claude/statusline.conf</code> — drobna shell datoteka.',
    'faq.q.free': 'Je brezplačno? Komercialno?',
    'faq.a.free': 'Osebna lokalna uporaba je brezplačna. Vsaka ponovna uporaba zahteva <strong>predhodno pisno dovoljenje</strong> avtorja.',
    'faq.q.time': 'Kako deluje sledilnik človeških ur?',
    'faq.a.time': 'Tema <strong>time</strong> bere časovne žige iz JSONL: <strong>active</strong> (vrzeli < 5 min) in <strong>wall</strong> (celoten razpon).',
    'faq.q.revert': 'Kako se vrnem na privzeto vrstico?',
    'faq.a.revert': 'Odstranite blok <code>statusLine</code> iz <code>~/.claude/settings.json</code>.',
    'faq.q.reset': 'Kaj pomeni 5h{1.1h}: 1%?',
    'faq.a.reset': 'Porabili ste 1 % 5-urnega okna, <code>{1.1h}</code> pa je živo odštevanje — okno se ponastavi čez 1,1 ure (<code>7d{1.1d}</code>: tedensko okno se ponastavi čez 1,1 dneva). Prebrano iz <code>rate_limits.*.resets_at</code> ob vsakem izrisu. V vaši gradnji ni časovnega žiga ponastavitve? Merilnik se povrne na preprosto <code>5h: 1%</code>.',
