    'install.sub': 'Iniziamo',
    'vibe.eyebrow': 'Install vibe-chill',
    'vibe.title': 'Perché toccare un terminale<br/>quando hai <em>Claude Code</em>?',
    'vibe.intro': 'Incolla questo unico prompt nella tua sessione Claude Code. Di\' "y" quando chiede il permesso. Fatto.',
    'vibe.bonus': 'Niente git, niente install di jq, niente caccia al <code class="mono">settings.json</code> — Claude gestisce ogni passo e chiede prima di ogni comando.',
    'vibe.panel.label': 'incolla in Claude Code:',
    'vibe.prompt': 'Installa claude-code-statusline di amazopic per me. Prima assicurati che jq sia installato (esegui `which jq`) — se manca, installalo per la piattaforma: `sudo apt-get install -y jq` (Ubuntu/Debian), `sudo dnf install -y jq` (Fedora), `brew install jq` (macOS), `sudo apk add jq` (Alpine). Poi leggi ~/.claude/settings.json — se c\'è statusLine.command che punta a un file esistente (es. ~/.claude/status-line.sh o altro percorso), fai un backup di quel file aggiungendo .bak (sovrascrivi qualsiasi .bak esistente). Anche se ~/.claude/status-line.sh esiste già — fanne un backup nello stesso modo. Poi clona github.com/amazopic/claude-code-statusline, copia statusline-bundle.sh in ~/.claude/status-line.sh e rendilo eseguibile, copia anche commands/statusline.md in ~/.claude/commands/. Aggiorna ~/.claude/settings.json così che statusLine = { type: "command", command: "<percorso assoluto a ~/.claude/status-line.sh>" }. Infine esegui ~/.claude/status-line.sh use developer per testare il tema developer e dimmi di riavviare Claude Code.',
    'vibe.note': '↳ Di\' semplicemente <code class="mono">y</code> (sì) a ogni richiesta di autorizzazione — Claude eseguirà ogni comando uno per uno.',
    'install.title': 'Installa in 30 secondi',
    'install.intro': 'Un singolo script bundle fa entrambi i lavori: rende la tua status line quando Claude Code la chiama, e funge da configuratore CLI quando lo chiami con argomenti.',
    'install.step1.title': 'Clona e copia',
    'install.step1.desc': 'Metti il bundle in <code class="mono">~/.claude/status-line.sh</code>.',
    'install.step2.title': 'Scegli un tema',
    'install.step2.desc': 'O componi blocchi via <code class="mono">custom</code>.',
    'install.step3.title': 'Collega',
    'install.step3.desc': 'Comunicalo a Claude Code in <code class="mono">settings.json</code>, riavvia.',
    'install.claude.label': 'O in Claude Code — il più facile',
    'install.claude.intro': 'Claude Code già aperto? Incolla questi due prompt — fatto, niente terminale.',
    'install.claude.prompt1': 'Installa claude-code-statusline di amazopic per me. Prima assicurati che jq sia installato (esegui `which jq`) — se manca, installalo per la piattaforma: `sudo apt-get install -y jq` (Ubuntu/Debian), `sudo dnf install -y jq` (Fedora), `brew install jq` (macOS), `sudo apk add jq` (Alpine). Poi leggi ~/.claude/settings.json — se c\'è statusLine.command che punta a un file esistente (es. ~/.claude/status-line.sh o altro percorso), fai un backup di quel file aggiungendo .bak (sovrascrivi qualsiasi .bak esistente). Anche se ~/.claude/status-line.sh esiste già — fanne un backup nello stesso modo. Poi clona github.com/amazopic/claude-code-statusline, copia statusline-bundle.sh in ~/.claude/status-line.sh e rendilo eseguibile, copia anche commands/statusline.md in ~/.claude/commands/. Aggiorna ~/.claude/settings.json così che statusLine = { type: "command", command: "<percorso assoluto a ~/.claude/status-line.sh>" }. Infine esegui ~/.claude/status-line.sh use developer per testare il tema developer e dimmi di riavviare Claude Code.',
    'install.claude.prompt2_label': 'Poi prova:',
    'install.codelabel.main': 'macOS / Linux / WSL',
    'install.codelabel.slash': 'Opzionale: comando slash <code class="mono">/statusline</code>',
    'faq.sub': 'D &amp; R',
    'faq.title': 'Domande<br/>frequenti',
    'faq.q.limits': 'Perché il display dei limiti 5h / 7g è la funzionalità principale?',
    'faq.a.limits': 'Perché è la lamentela n°1 dopo aver comprato un piano Claude: la status line predefinita dà <strong>zero visibilità</strong> sui tuoi limiti. Lo scopri solo quando Claude rifiuta di rispondere. Questo script legge i dati <code>limits</code>, mostra entrambi gli indicatori in tempo reale e attiva un ⚠️ allarme oltre il 50 %.',
    'faq.q.what': 'Cos\'è "Claude Code Status Line"?',
    'faq.a.what': 'Una sostituzione bash della status line predefinita in <a href="https://claude.com/claude-code">Claude Code</a>. Trasforma la riga in basso in un vero cruscotto: modello, % contesto, barra di progresso, costo sessione, <strong>limiti 5h / 7g</strong>, status git, tempo task e altro.',
    'faq.q.install': 'Come si installa?',
    'faq.a.install': 'Copia <code>statusline-bundle.sh</code> in <code>~/.claude/status-line.sh</code>, fai <code>chmod +x</code>, poi punta <code>~/.claude/settings.json</code> a quel percorso.',
    'faq.q.update': 'Come aggiorno all\'ultima versione?',
    'faq.a.update': 'Esegui <code>~/.claude/status-line.sh update</code>. Il comando scarica l\'ultimo bundle da GitHub, crea un backup con timestamp (<code>~/.claude/status-line.sh.bak.&lt;YYYYMMDD-HHMMSS&gt;</code>) e preserva la tua configurazione del tema. Riavvia Claude Code dopo. Controlla la versione installata: <code>~/.claude/status-line.sh version</code>.',
    'faq.q.1m': 'Supporta i modelli con contesto 1M?',
    'faq.a.1m': 'Sì. Lo script rileva <code>[1m]</code> nell\'id e <code>1M</code> nel nome, regola il denominatore a 1.000.000 token.',
    'faq.q.models': 'Con quali modelli funziona?',
    'faq.a.models': 'Con qualsiasi modello supportato da Claude Code — Opus 4.7, Sonnet 4.6, Haiku 4.5, Opus 4.6 ecc.',
    'faq.q.customize': 'Posso personalizzare colori, temi, aggiungerne miei?',
    'faq.a.customize': 'Sì, in tre modi: scegli uno dei 158 preset, componi il tuo dai blocchi, o modifica <code>statusline.sh</code> direttamente.',
    'faq.q.perf': 'Rallenterà Claude Code?',
    'faq.a.perf': 'No. Rendering tipico ≤ 50 ms anche con tracker temporale attivo.',
    'faq.q.jq': 'Funziona senza jq?',
    'faq.a.jq': '<code>jq</code> è richiesto — analizza il JSON.',
    'faq.q.win': 'Funziona su Windows?',
    'faq.a.win': 'Sì, in qualsiasi ambiente con <code>bash</code> 4+ e <code>jq</code> — Git Bash, WSL, MSYS2, Cygwin.',
    'faq.q.conf': 'Dov\'è memorizzata la configurazione?',
    'faq.a.conf': '<code>~/.claude/statusline.conf</code> — un piccolo file shell.',
    'faq.q.free': 'È gratis? Uso commerciale?',
    'faq.a.free': 'Uso personale locale gratis. Qualsiasi riuso richiede <strong>permesso scritto preventivo</strong> dell\'autore.',
    'faq.q.time': 'Come funziona il tracker delle ore-uomo?',
    'faq.a.time': 'Il tema <strong>time</strong> legge i timestamp dal JSONL: <strong>active</strong> (gap < 5 min) e <strong>wall</strong> (intervallo totale).',
    'faq.q.revert': 'Come torno alla status line predefinita?',
    'faq.a.revert': 'Rimuovi il blocco <code>statusLine</code> da <code>~/.claude/settings.json</code>.',
    'faq.q.reset': 'Cosa significa 5h{1.1h}: 1%?',
    'faq.a.reset': 'Hai usato l\'1% della finestra di 5 ore, e <code>{1.1h}</code> è un conto alla rovescia in tempo reale — la finestra si resetta tra 1,1 ore (<code>7d{1.1d}</code>: la finestra settimanale si resetta tra 1,1 giorni). Letto da <code>rate_limits.*.resets_at</code> a ogni render. Nessun timestamp di reset nella tua build? L\'indicatore torna al semplice <code>5h: 1%</code>.',
    'colo.title': 'Amazopic',
    'colo.h.author': 'Autore',
