    'hero.limits.body': '¿Compraste un plan Pro y te sigues topando con el límite de 5 horas o 7 días a mitad de tarea? La línea predeterminada nunca te avisa. <strong>Esta sí.</strong> Medidores 5h / 7d en vivo, ⚠️ alerta sobre 50 %, integrado en cada tema.',
