    'recipe.empty.line': 'arrastra bloques aquí…',
    'recipe.empty.preview': '// añade bloques para ver tu línea',
    'install.sub': 'Empezamos',
    'vibe.eyebrow': 'Instalación vibe-chill',
    'vibe.title': '¿Para qué tocar un terminal<br/>si tienes <em>Claude Code</em>?',
    'vibe.intro': 'Pega este único prompt en tu sesión de Claude Code. Di "y" cuando te pida permiso. Listo.',
    'vibe.bonus': 'Sin git, sin instalar jq, sin buscar en <code class="mono">settings.json</code> — Claude maneja cada paso y pregunta antes de cada comando.',
    'vibe.panel.label': 'pega en Claude Code:',
    'vibe.prompt': 'Instálame claude-code-statusline de amazopic. Primero asegúrate de que jq esté instalado (ejecuta `which jq`) — si falta, instálalo según la plataforma: `sudo apt-get install -y jq` (Ubuntu/Debian), `sudo dnf install -y jq` (Fedora), `brew install jq` (macOS), `sudo apk add jq` (Alpine). Luego lee ~/.claude/settings.json — si hay statusLine.command apuntando a un archivo existente (ej: ~/.claude/status-line.sh u otra ruta), haz una copia de seguridad de ese archivo añadiendo .bak (sobrescribe cualquier .bak existente). También si ~/.claude/status-line.sh ya existe — hazle backup igual. Luego clona github.com/amazopic/claude-code-statusline, copia statusline-bundle.sh a ~/.claude/status-line.sh y hazlo ejecutable, copia también commands/statusline.md a ~/.claude/commands/. Actualiza ~/.claude/settings.json para que statusLine = { type: "command", command: "<ruta absoluta a ~/.claude/status-line.sh>" }. Por último ejecuta ~/.claude/status-line.sh use developer para probar el tema developer y dime que reinicie Claude Code.',
    'vibe.note': '↳ Solo di <code class="mono">y</code> (sí) en cada petición de permiso — Claude ejecutará cada comando uno por uno.',
    'install.title': 'Instalar en 30 segundos',
    'install.intro': 'Un único script bundle hace ambos trabajos: renderiza tu línea de estado cuando Claude Code lo llama, y actúa como configurador CLI cuando lo llamas con argumentos.',
    'install.step1.title': 'Clonar y copiar',
    'install.step1.desc': 'Pon el bundle en <code class="mono">~/.claude/status-line.sh</code>.',
    'install.step2.title': 'Elegir tema',
    'install.step2.desc': 'O compón bloques vía <code class="mono">custom</code>.',
    'install.step3.title': 'Conectar',
    'install.step3.desc': 'Indícaselo a Claude Code en <code class="mono">settings.json</code>, reinicia.',
    'install.claude.label': 'O en Claude Code — lo más fácil',
    'install.claude.intro': '¿Ya tienes Claude Code abierto? Pega estos dos prompts y listo — sin terminal.',
    'install.claude.prompt1': 'Instálame claude-code-statusline de amazopic. Primero asegúrate de que jq esté instalado (ejecuta `which jq`) — si falta, instálalo según la plataforma: `sudo apt-get install -y jq` (Ubuntu/Debian), `sudo dnf install -y jq` (Fedora), `brew install jq` (macOS), `sudo apk add jq` (Alpine). Luego lee ~/.claude/settings.json — si hay statusLine.command apuntando a un archivo existente (ej: ~/.claude/status-line.sh u otra ruta), haz una copia de seguridad de ese archivo añadiendo .bak (sobrescribe cualquier .bak existente). También si ~/.claude/status-line.sh ya existe — hazle backup igual. Luego clona github.com/amazopic/claude-code-statusline, copia statusline-bundle.sh a ~/.claude/status-line.sh y hazlo ejecutable, copia también commands/statusline.md a ~/.claude/commands/. Actualiza ~/.claude/settings.json para que statusLine = { type: "command", command: "<ruta absoluta a ~/.claude/status-line.sh>" }. Por último ejecuta ~/.claude/status-line.sh use developer para probar el tema developer y dime que reinicie Claude Code.',
    'install.claude.prompt2_label': 'Luego prueba:',
    'install.codelabel.main': 'macOS / Linux / WSL',
    'install.codelabel.slash': 'Opcional: comando slash <code class="mono">/statusline</code>',
    'faq.sub': 'P &amp; R',
    'faq.title': 'Preguntas<br/>frecuentes',
    'faq.q.limits': '¿Por qué el display de límites 5h / 7d es la característica estrella?',
    'faq.a.limits': 'Porque es la queja #1 tras comprar un plan Claude: la línea predeterminada da <strong>cero visibilidad</strong> de tus límites de 5 horas y 7 días. Solo te enteras cuando Claude se niega a responder. Este script lee <code>limits</code>, muestra ambos medidores en vivo y dispara una ⚠️ alerta visual sobre el 50 %.',
    'faq.q.what': '¿Qué es "Claude Code Status Line"?',
    'faq.a.what': 'Un reemplazo bash de la línea de estado predeterminada en <a href="https://claude.com/claude-code">Claude Code</a>. Convierte la línea inferior en un panel real: modelo, % contexto, barra de progreso, costo sesión, <strong>límites 5h / 7d</strong>, estado git, tiempo de tarea y más.',
    'faq.q.install': '¿Cómo se instala?',
    'faq.a.install': 'Copia <code>statusline-bundle.sh</code> en <code>~/.claude/status-line.sh</code>, haz <code>chmod +x</code>, luego apunta <code>~/.claude/settings.json</code> a esa ruta.',
    'faq.q.update': '¿Cómo actualizo a la última versión?',
    'faq.a.update': 'Ejecuta <code>~/.claude/status-line.sh update</code>. El comando descarga el último bundle desde GitHub, crea una copia de seguridad con marca de tiempo (<code>~/.claude/status-line.sh.bak.&lt;YYYYMMDD-HHMMSS&gt;</code>) y conserva tu configuración de tema. Reinicia Claude Code después. Comprueba la versión instalada: <code>~/.claude/status-line.sh version</code>.',
    'faq.q.1m': '¿Soporta modelos de contexto 1M?',
    'faq.a.1m': 'Sí. El script detecta <code>[1m]</code> en el id y <code>1M</code> en el nombre, ajusta el denominador a 1.000.000 tokens.',
    'faq.q.models': '¿Con qué modelos funciona?',
