    'vibe.panel.label': '粘到 Claude Code 里：',
    'vibe.prompt': '帮我安装 amazopic 的 claude-code-statusline。先确认已安装 jq（运行 `which jq`）— 如果没有，按平台安装：`sudo apt-get install -y jq`（Ubuntu/Debian）、`sudo dnf install -y jq`（Fedora）、`brew install jq`（macOS）、`sudo apk add jq`（Alpine）。然后读 ~/.claude/settings.json — 如果其中有 statusLine.command 指向某个已存在的文件（如 ~/.claude/status-line.sh 或其他路径），把那个文件加 .bak 后缀做备份（覆盖已有的 .bak）。如果 ~/.claude/status-line.sh 也已存在，同样备份。然后克隆 github.com/amazopic/claude-code-statusline，把 statusline-bundle.sh 复制到 ~/.claude/status-line.sh 并设为可执行，再把 commands/statusline.md 复制到 ~/.claude/commands/。更新 ~/.claude/settings.json 使 statusLine = { type: "command", command: "<~/.claude/status-line.sh 的绝对路径>" }。最后运行 ~/.claude/status-line.sh use developer 测试 developer 主题，并提醒我重启 Claude Code。',
    'vibe.note': '↳ 每个权限提示都回 <code class="mono">y</code>（yes）即可 — Claude 会逐条执行。',
