    'hero.limits.badge': '★ NEW · インストールする一番の理由',
    'hero.limits.title': 'リミット管理。<br/>最高の生産性。<br/><em>サプライズなし。</em>',
    'hero.limits.body': 'Pro プランを買ったのに、作業の途中で 5 時間 / 7 日のリミットにずっとぶつかってる？デフォルトのステータスラインは警告してくれません。<strong>これは警告します。</strong>5h / 7d のライブメーター、50% を超えると ⚠️ アラート、すべてのテーマに組み込み済み。',
