    'install.claude.label': 'または Claude Code 内で — 一番簡単',
    'install.claude.intro': 'Claude Code を開いている？この 2 つのプロンプトを貼り付けるだけ — ターミナル不要。',
    'install.claude.prompt1': 'amazopic の claude-code-statusline をインストールして。まず jq がインストールされているか確認（`which jq` を実行）— 入っていなければプラットフォームに合わせて入れて：`sudo apt-get install -y jq`（Ubuntu/Debian）、`sudo dnf install -y jq`（Fedora）、`brew install jq`（macOS）、`sudo apk add jq`（Alpine）。次に ~/.claude/settings.json を読んで — statusLine.command が既存ファイル（例：~/.claude/status-line.sh など）を指していたら、そのファイルに .bak を追加してバックアップ（既存 .bak は上書き）。~/.claude/status-line.sh が既にあれば同様にバックアップ。次に github.com/amazopic/claude-code-statusline をクローンし、statusline-bundle.sh を ~/.claude/status-line.sh にコピーして実行可能にし、commands/statusline.md も ~/.claude/commands/ にコピー。~/.claude/settings.json を更新して statusLine = { type: "command", command: "<~/.claude/status-line.sh の絶対パス>" } にして。最後に ~/.claude/status-line.sh use developer を実行して developer テーマをテストし、Claude Code を再起動するよう伝えて。',
    'install.claude.prompt2_label': 'そしてテスト：',
    'install.codelabel.main': 'macOS / Linux / WSL',
    'install.codelabel.slash': 'オプション：<code class="mono">/statusline</code> スラッシュコマンド',
    'faq.sub': 'Q &amp; A',
    'faq.title': 'よくある<br/>質問',
    'faq.q.limits': 'なぜ 5h / 7d リミット表示が目玉機能なのですか？',
    'faq.a.limits': 'Claude プラン購入後の不満トップ 1 だからです：デフォルトのステータスラインは 5 時間と 7 日のリミットについて<strong>まったく可視化しません</strong>。Claude が応答を拒否して初めて気づきます。このスクリプトはライブの JSON から <code>limits</code> を読み、両メーターをリアルタイム描画、50% 超で ⚠️ ビジュアルアラートを発動します。',
    'faq.q.what': '「Claude Code Status Line」とは？',
    'faq.a.what': '<a href="https://claude.com/claude-code">Claude Code</a>（Anthropic の CLI）のデフォルトステータスラインの bash 製代替品。画面下部の行を本格的なダッシュボードに変えます：モデル、コンテキスト%、プログレスバー、セッションコスト、<strong>5h / 7d リミット</strong>、git 状態、タスク時間など。',
    'faq.q.install': 'インストール方法は？',
    'faq.a.install': '<code>statusline-bundle.sh</code> を <code>~/.claude/status-line.sh</code> にコピーし、<code>chmod +x</code>、そして <code>~/.claude/settings.json</code> の <code>statusLine.command</code> をそのパスに向けます。',
    'faq.q.update': '最新バージョンへの更新方法は?',
    'faq.a.update': '<code>~/.claude/status-line.sh update</code> を実行してください。GitHub から最新の bundle を取得し、タイムスタンプ付きバックアップ（<code>~/.claude/status-line.sh.bak.&lt;YYYYMMDD-HHMMSS&gt;</code>）を作成、テーマ設定を保持します。完了後 Claude Code を再起動してください。インストール済みバージョンの確認: <code>~/.claude/status-line.sh version</code>。',
    'faq.q.1m': '1M コンテキストモデルをサポート？',
    'faq.a.1m': 'はい。スクリプトは model id の <code>[1m]</code> と表示名の <code>1M</code> を検出し、バーの分母を 1,000,000 トークンに調整します。',
    'faq.q.models': 'どのモデルで動きますか？',
    'faq.a.models': 'Claude Code がサポートするどのモデルでも — Opus 4.7、Sonnet 4.6、Haiku 4.5、Opus 4.6 など。',
    'faq.q.customize': '色やテーマをカスタマイズ、自作できますか？',
    'faq.a.customize': 'はい、3 つの方法：158 のプリセットから選ぶ、Recipe Builder で名前付きブロックから組み合わせる、<code>statusline.sh</code> を直接編集する。',
    'faq.q.perf': 'Claude Code が遅くなりますか？',
    'faq.a.perf': 'いいえ。時間トラッカー有効でも典型レンダリングは ≤ 50 ミリ秒。',
    'faq.q.jq': 'jq なしで動く？',
    'faq.a.jq': '<code>jq</code> は必須 — JSON をパースします。',
    'faq.q.win': 'Windows で動く？',
    'faq.a.win': 'はい、<code>bash</code> 4+ と <code>jq</code> がある環境で — Git Bash、WSL、MSYS2、Cygwin。',
    'faq.q.conf': '設定はどこに保存される？',
    'faq.a.conf': '<code>~/.claude/statusline.conf</code> — 小さな shell ファイル。',
    'faq.q.free': '無料？商用利用は？',
    'faq.a.free': '個人ローカル利用は無料。再利用には著者の<strong>書面による事前許可</strong>が必要です。',
    'faq.q.time': '人時間トラッカーの仕組みは？',
    'faq.a.time': '<strong>time</strong> テーマは JSONL のタイムスタンプを読み、<strong>active</strong>（5 分未満のギャップ）と <strong>wall</strong>（最初から最後の総スパン）を報告します。',
    'faq.q.revert': 'デフォルトのステータスラインに戻すには？',
    'faq.a.revert': '<code>~/.claude/settings.json</code> から <code>statusLine</code> ブロックを削除します。',
    'faq.q.reset': '5h{1.1h}: 1% とはどういう意味ですか？',
    'faq.a.reset': '5 時間ウィンドウの 1% を使用しており、<code>{1.1h}</code> はライブのカウントダウンです — ウィンドウは 1.1 時間後にリセットされます（<code>7d{1.1d}</code>：週間ウィンドウは 1.1 日後にリセット）。レンダリングのたびに <code>rate_limits.*.resets_at</code> から読み取ります。お使いのビルドがリセットのタイムスタンプを送らない場合、メーターはシンプルな <code>5h: 1%</code> にフォールバックします。',
