    'note.label': '편집자 주',
    'note.body.p1': '<span class="dropcap">C</span>laude Code는 <strong>빈약한</strong> 상태줄로 출시됩니다. 모델 이름. 운이 좋으면 디렉터리. 그게 다입니다. 그동안 컨텍스트는 채워지고, <strong>5시간과 7일 한도는 줄어들고</strong>, 세션은 조용히 비용을 누적합니다 — 한도를 넘긴 뒤에야 알게 되죠.',
