    'specimens.group': '그룹',
    'specimens.try.label': 'Claude Code에서 바로 사용해보기',
    'specimens.try.intro': '이미 Claude Code 세션 중인가요? 인수와 함께 <code class="mono">/statusline</code>을 입력하세요 — 내장 슬래시 명령이 모든 호출을 아래 번들로 전달합니다.',
    'specimens.try.caption': '같은 스크립트, 두 가지 모드 — <strong>stdin = 렌더링</strong>, <strong>인수 = 설정</strong>. <code class="mono">~/.claude/commands/statusline.md</code>로 이미 제공됨.',
