    'install.sub': '시작하기',
    'vibe.eyebrow': 'Vibe-chill 설치',
    'vibe.title': '<em>Claude Code</em>가 있는데<br/>왜 터미널을 만져요?',
    'vibe.intro': '이 한 프롬프트를 Claude Code 세션에 붙여넣으세요. 권한 요청에 "y"라고 답하면 끝.',
    'vibe.bonus': 'git 없이, jq 설치 없이, <code class="mono">settings.json</code> 뒤지기 없이 — Claude가 모든 단계를 처리하고 각 명령 전에 물어봅니다.',
    'vibe.panel.label': 'Claude Code에 붙여넣기:',
    'vibe.prompt': 'amazopic의 claude-code-statusline을 설치해줘. 먼저 jq가 설치되어 있는지 확인해줘(`which jq` 실행) — 없으면 플랫폼에 맞게 설치: `sudo apt-get install -y jq`(Ubuntu/Debian), `sudo dnf install -y jq`(Fedora), `brew install jq`(macOS), `sudo apk add jq`(Alpine). 그다음 ~/.claude/settings.json을 읽고 — statusLine.command가 기존 파일(예: ~/.claude/status-line.sh 등)을 가리키면, 그 파일에 .bak를 붙여 백업해(기존 .bak는 덮어씀). ~/.claude/status-line.sh도 이미 있으면 같은 방식으로 백업. 그다음 github.com/amazopic/claude-code-statusline을 클론하고, statusline-bundle.sh를 ~/.claude/status-line.sh에 복사한 뒤 실행 가능하게 만들고, commands/statusline.md도 ~/.claude/commands/에 복사. ~/.claude/settings.json을 업데이트해서 statusLine = { type: "command", command: "<~/.claude/status-line.sh의 절대 경로>" }로 만들어줘. 마지막으로 ~/.claude/status-line.sh use developer를 실행해 developer 테마를 테스트하고 Claude Code 재시작하라고 알려줘.',
    'vibe.note': '↳ 권한 프롬프트마다 <code class="mono">y</code>(yes)라고만 답하면 됩니다 — Claude가 명령을 하나씩 실행합니다.',
    'install.title': '30초 안에 설치',
    'install.intro': '하나의 번들 스크립트가 두 가지 일을 합니다: Claude Code가 호출하면 상태줄을 렌더링하고, 인수와 함께 호출하면 CLI 설정 도구로 동작합니다.',
    'install.step1.title': '복제 및 복사',
    'install.step1.desc': '번들을 <code class="mono">~/.claude/status-line.sh</code>에 배치.',
    'install.step2.title': '테마 선택',
    'install.step2.desc': '또는 <code class="mono">custom</code>으로 블록 조합.',
    'install.step3.title': '연결',
    'install.step3.desc': '<code class="mono">settings.json</code>에서 Claude Code에 알리고 재시작.',
    'install.claude.label': '또는 Claude Code에서 — 가장 쉬운 방법',
    'install.claude.intro': 'Claude Code가 이미 열려있나요? 이 두 프롬프트를 붙여넣으면 끝 — 터미널 필요 없음.',
    'install.claude.prompt1': 'amazopic의 claude-code-statusline을 설치해줘. 먼저 jq가 설치되어 있는지 확인해줘(`which jq` 실행) — 없으면 플랫폼에 맞게 설치: `sudo apt-get install -y jq`(Ubuntu/Debian), `sudo dnf install -y jq`(Fedora), `brew install jq`(macOS), `sudo apk add jq`(Alpine). 그다음 ~/.claude/settings.json을 읽고 — statusLine.command가 기존 파일(예: ~/.claude/status-line.sh 등)을 가리키면, 그 파일에 .bak를 붙여 백업해(기존 .bak는 덮어씀). ~/.claude/status-line.sh도 이미 있으면 같은 방식으로 백업. 그다음 github.com/amazopic/claude-code-statusline을 클론하고, statusline-bundle.sh를 ~/.claude/status-line.sh에 복사한 뒤 실행 가능하게 만들고, commands/statusline.md도 ~/.claude/commands/에 복사. ~/.claude/settings.json을 업데이트해서 statusLine = { type: "command", command: "<~/.claude/status-line.sh의 절대 경로>" }로 만들어줘. 마지막으로 ~/.claude/status-line.sh use developer를 실행해 developer 테마를 테스트하고 Claude Code 재시작하라고 알려줘.',
    'install.claude.prompt2_label': '그런 다음 테스트:',
    'install.codelabel.main': 'macOS / Linux / WSL',
    'install.codelabel.slash': '선택: <code class="mono">/statusline</code> 슬래시 명령',
    'faq.sub': 'Q &amp; A',
    'faq.title': '자주 묻는<br/>질문',
    'faq.q.limits': '왜 5h / 7d 한도 표시가 핵심 기능인가요?',
    'faq.a.limits': 'Claude 플랜 구매 후 가장 많은 불평이기 때문입니다: 기본 상태줄은 5시간과 7일 한도에 대해 <strong>가시성이 전혀 없습니다</strong>. Claude가 응답을 거부하고 나서야 알게 됩니다. 이 스크립트는 <code>limits</code> 데이터를 읽어 두 미터를 실시간으로 그리고, 50% 초과 시 ⚠️ 시각 경고를 띄웁니다.',
    'faq.q.what': '"Claude Code Status Line"이란?',
    'faq.a.what': '<a href="https://claude.com/claude-code">Claude Code</a>(Anthropic의 CLI) 기본 상태줄의 bash 기반 대체품. 화면 하단 줄을 진정한 대시보드로 바꿉니다: 모델, 컨텍스트%, 진행 바, 세션 비용, <strong>5h / 7d 한도</strong>, git 상태, 작업 시간 등.',
    'faq.q.install': '설치 방법은?',
    'faq.a.install': '<code>statusline-bundle.sh</code>를 <code>~/.claude/status-line.sh</code>에 복사, <code>chmod +x</code>, <code>~/.claude/settings.json</code>의 <code>statusLine.command</code>을 해당 경로로 지정.',
    'faq.q.update': '최신 버전으로 어떻게 업데이트하나요?',
    'faq.a.update': '<code>~/.claude/status-line.sh update</code>를 실행하세요. GitHub에서 최신 bundle을 가져오고, 타임스탬프 백업(<code>~/.claude/status-line.sh.bak.&lt;YYYYMMDD-HHMMSS&gt;</code>)을 만들며, 테마 설정을 보존합니다. 그 후 Claude Code를 재시작하세요. 설치된 버전 확인: <code>~/.claude/status-line.sh version</code>.',
    'faq.q.1m': '1M 컨텍스트 모델 지원?',
    'faq.a.1m': '예. 스크립트는 model id의 <code>[1m]</code>과 표시 이름의 <code>1M</code>을 감지하여 바의 분모를 1,000,000 토큰으로 조정합니다.',
    'faq.q.models': '어떤 모델에서 동작?',
    'faq.a.models': 'Claude Code가 지원하는 모든 모델 — Opus 4.7, Sonnet 4.6, Haiku 4.5, Opus 4.6 등.',
    'faq.q.customize': '색상, 테마를 커스터마이징하거나 추가할 수 있나요?',
    'faq.a.customize': '예, 세 가지 방법: 158개 프리셋 중 선택, Recipe builder로 명명된 블록 조합, <code>statusline.sh</code> 직접 편집.',
    'faq.q.perf': 'Claude Code가 느려지나요?',
    'faq.a.perf': '아니오. 시간 추적기 활성화 시에도 일반 렌더링 ≤ 50ms.',
    'faq.q.jq': 'jq 없이 동작하나요?',
    'faq.a.jq': '<code>jq</code> 필수 — JSON 파싱.',
    'faq.q.win': 'Windows에서 동작?',
    'faq.a.win': '예, <code>bash</code> 4+와 <code>jq</code>가 있는 환경 — Git Bash, WSL, MSYS2, Cygwin.',
    'faq.q.conf': '설정은 어디 저장되나요?',
    'faq.a.conf': '<code>~/.claude/statusline.conf</code> — 작은 shell 파일.',
    'faq.q.free': '무료? 상업적 사용?',
    'faq.a.free': '개인 로컬 사용 무료. 재사용은 저자의 <strong>사전 서면 허가</strong> 필요.',
    'faq.q.time': '인시 추적기는 어떻게 동작?',
    'faq.a.time': '<strong>time</strong> 테마는 JSONL 타임스탬프 읽음: <strong>active</strong>(5분 미만 간격) 및 <strong>wall</strong>(첫-마지막 메시지 총 범위).',
    'faq.q.revert': '기본 상태줄로 되돌리려면?',
    'faq.a.revert': '<code>~/.claude/settings.json</code>에서 <code>statusLine</code> 블록을 제거.',
    'faq.q.reset': '5h{1.1h}: 1% 는 무슨 뜻인가요?',
    'faq.a.reset': '5시간 창의 1%를 사용했고, <code>{1.1h}</code> 는 실시간 카운트다운입니다 — 창은 1.1시간 후에 리셋됩니다 (<code>7d{1.1d}</code>: 주간 창은 1.1일 후에 리셋). 렌더링할 때마다 <code>rate_limits.*.resets_at</code> 에서 읽습니다. 빌드에 리셋 타임스탬프가 없나요? 미터는 단순한 <code>5h: 1%</code> 로 폴백합니다.',
