    'recipe.title': 'أنشئ<br/>ما يخصك',
    'recipe.intro': 'اضغط على الكتل لإضافتها إلى شريط الحالة. شاهدها تُعرض مباشرة. انسخ bash وانطلق.',
    'recipe.palette.h': 'الكتل المتاحة',
