    'catalog.meta': 'Conteúdo · 158 espécimes',
    'catalog.title': 'O Catálogo<br/><em>em dois volumes — detalhado &amp; compacto</em>',
    'catalog.intro': 'Setenta e nove temas, cada um em dois acabamentos — detalhado e compacto. Toque em um nome para ir até a página do espécime.',
    'specimens.title': 'Espécimes',
    'specimens.prev': 'Espécime anterior',
