    'specimens.source': 'fonte:',
    'specimens.detailed': 'Detalhado',
    'specimens.compact': 'Compacto',
    'specimens.palette': 'Paleta',
    'specimens.glyphs': 'Kit de glifos',
    'specimens.group': 'Grupo',
    'specimens.try.label': 'Experimente de dentro do Claude Code',
    'specimens.try.intro': 'Já está numa sessão do Claude Code? É só digitar <code class="mono">/statusline</code> com argumentos — o comando slash incluído roteia tudo para o bundle abaixo.',
    'specimens.try.caption': 'O mesmo script, dois modos — <strong>stdin = renderizar</strong>, <strong>args = configurar</strong>. Já incluído como <code class="mono">~/.claude/commands/statusline.md</code>.',
