    'hero.limits.title': 'Limit kontrolü.<br/>Maksimum verimlilik.<br/><em>Sıfır sürpriz.</em>',
    'hero.limits.body': 'Bir Pro plan aldınız ama hâlâ görev ortasında 5 saatlik veya 7 günlük sınıra mı toslayıp duruyorsunuz? Varsayılan durum satırı sizi asla uyarmaz. <strong>Bu uyarır.</strong> Canlı 5sa / 7g göstergeleri, %50 üzerinde ⚠️ uyarı, her temaya işlenmiş.',
