    'specimens.try.label': 'Claude Code içinden deneyin',
    'specimens.try.intro': 'Zaten bir Claude Code oturumunda mısınız? Argümanlarla <code class="mono">/statusline</code> yazmanız yeterli — gönderilen slash komutu her şeyi aşağıdaki pakete yönlendirir.',
    'specimens.try.caption': 'Aynı betik, iki mod — <strong>stdin = render</strong>, <strong>args = yapılandırma</strong>. Zaten <code class="mono">~/.claude/commands/statusline.md</code> olarak gönderildi.',

    'compare.sub': 'Yan yana karşılaştırma',
    'compare.title': 'varsayılan durum<br/>satırına karşı',
    'compare.col.feature': 'Yetenek',
