    'vibe.title': '都有 <em>Claude Code</em> 了，<br/>何必動終端機？',
    'vibe.intro': '把這一段提示詞貼進你的 Claude Code 工作階段。每次它徵詢權限時回「y」。搞定。',
    'vibe.bonus': '不用 git、不用搞 jq 安裝那一套、不用翻 <code class="mono">settings.json</code> — Claude 全程包辦每個步驟，而且每條指令前都會先問你。',
    'vibe.panel.label': '貼進 Claude Code：',
    'vibe.prompt': '幫我安裝 amazopic 的 claude-code-statusline。先確認已安裝 jq（執行 `which jq`）— 若缺少，請依平台安裝：`sudo apt-get install -y jq`（Ubuntu/Debian）、`sudo dnf install -y jq`（Fedora）、`brew install jq`（macOS）、`sudo apk add jq`（Alpine）。接著讀取 ~/.claude/settings.json — 如果其中有 statusLine.command 指向某個既有檔案（例如 ~/.claude/status-line.sh 或其他路徑），請在該檔名後加上 .bak 進行備份（覆寫任何既有的 .bak）。另外若 ~/.claude/status-line.sh 已存在，也以相同方式備份。然後 clone github.com/amazopic/claude-code-statusline，把 statusline-bundle.sh 複製到 ~/.claude/status-line.sh 並設為可執行，也把 commands/statusline.md 複製到 ~/.claude/commands/。更新 ~/.claude/settings.json 使 statusLine 為 { type: "command", command: "<~/.claude/status-line.sh 的絕對路徑>" }。最後執行 ~/.claude/status-line.sh use developer 來測試 developer 佈景主題，並提醒我重新啟動 Claude Code。',
    'vibe.note': '↳ 在每個權限提示時都回 <code class="mono">y</code>（yes）即可 — Claude 會逐一執行每條指令。',
