    'install.step3.title': '接上線',
    'install.step3.desc': '在 <code class="mono">settings.json</code> 裡告訴 Claude Code，然後重新啟動。',
    'install.claude.label': '或在 Claude Code 中 — 最簡單',
    'install.claude.intro': '已經開著 Claude Code？貼上這兩段提示詞就完成了 — 不必動終端機。',
    'install.claude.prompt1': '幫我安裝 amazopic 的 claude-code-statusline。先確認已安裝 jq（執行 `which jq`）— 若缺少，請依平台安裝：`sudo apt-get install -y jq`（Ubuntu/Debian）、`sudo dnf install -y jq`（Fedora）、`brew install jq`（macOS）、`sudo apk add jq`（Alpine）。接著讀取 ~/.claude/settings.json — 如果其中有 statusLine.command 指向某個既有檔案（例如 ~/.claude/status-line.sh 或其他路徑），請在該檔名後加上 .bak 進行備份（覆寫任何既有的 .bak）。另外若 ~/.claude/status-line.sh 已存在，也以相同方式備份。然後 clone github.com/amazopic/claude-code-statusline，把 statusline-bundle.sh 複製到 ~/.claude/status-line.sh 並設為可執行，也把 commands/statusline.md 複製到 ~/.claude/commands/。更新 ~/.claude/settings.json 使 statusLine 為 { type: "command", command: "<~/.claude/status-line.sh 的絕對路徑>" }。最後執行 ~/.claude/status-line.sh use developer 來測試 developer 佈景主題，並提醒我重新啟動 Claude Code。',
    'install.claude.prompt2_label': '接著測試它：',
    'install.codelabel.main': 'macOS / Linux / WSL',
    'install.codelabel.slash': '選用：<code class="mono">/statusline</code> 斜線指令',

    'faq.sub': '問 &amp; 答',
    'faq.title': '常見<br/>問題',
    'faq.q.limits': '為什麼 5h / 7d 限制顯示是頭號功能？',
    'faq.a.limits': '因為這正是使用者買了 Claude 方案後抱怨最多的一點：預設的 Claude Code 狀態列對你的 5 小時與 7 天用量限制<strong>毫無可見性</strong>。你往往要等到 Claude 在任務中途拒絕回應時，才發現自己已經撞上限。這支腳本會從即時 JSON 讀取 <code>limits</code> 資料、即時算繪兩個量表，並在你越過 50% 時觸發 ⚠️ 視覺警示 — 讓你能在撞牆前就規劃好工作階段。',
    'faq.q.what': '什麼是「Claude Code Status Line」？',
    'faq.a.what': '一套以 bash 為基礎、用來取代 <a href="https://claude.com/claude-code">Claude Code</a>（Anthropic 的 CLI）預設狀態列的方案。它把螢幕底部那一行變成真正的儀表板：模型、脈絡百分比、進度條、工作階段成本、<strong>5h / 7d 限制</strong>、git 狀態、任務耗時等等。',
    'faq.q.install': '要如何安裝？',
    'faq.a.install': '把 <code>statusline-bundle.sh</code> 複製到 <code>~/.claude/status-line.sh</code>，執行 <code>chmod +x</code>，然後把 Claude Code 的 <code>~/.claude/settings.json</code> 中 <code>statusLine.command</code> 指向該路徑。完整說明見上方的安裝章節。',
    'faq.q.update': '要怎麼更新到最新版本？',
    'faq.a.update': '執行 <code>~/.claude/status-line.sh update</code>。它會從 GitHub 抓取最新套件、建立帶時間戳記的備份（<code>~/.claude/status-line.sh.bak.&lt;YYYYMMDD-HHMMSS&gt;</code>），並保留你的佈景主題設定。完成後請重新啟動 Claude Code。用 <code>~/.claude/status-line.sh version</code> 查看目前的版本。',
    'faq.q.1m': '它支援 1M 脈絡視窗的模型嗎？',
    'faq.a.1m': '支援。腳本會偵測模型 id 中的 <code>[1m]</code> 與顯示名稱中的 <code>1M</code>，並把進度條的分母調整為 1,000,000 個 tokens。你會看到 <code>Opus 4.7 (1M) … 12 % █▌░░░░░░░░ 121.4K/1000K</code>。',
    'faq.q.models': '它能搭配哪些模型？',
    'faq.a.models': '任何 Claude Code 支援的模型 — Opus 4.7、Sonnet 4.6、Haiku 4.5、Opus 4.6 等等。腳本會從 stdin 的 JSON 讀取 <code>model.display_name</code> 與 <code>model.id</code>；並不會把模型名稱寫死。',
    'faq.q.customize': '我能自訂顏色、佈景主題，或加入自己的嗎？',
    'faq.a.customize': '可以 — 有三種方式：(1) 從「樣本」章節的 <strong>158 種現成變體</strong>中挑一個，(2) 用上方的配方建構器，從<strong>具名區塊</strong>組合出自己的，(3) 直接在 <code>statusline.sh</code> 裡編輯顏色常數與進度條樣式。',
    'faq.q.perf': '它會拖慢 Claude Code 嗎？',
    'faq.a.perf': '不會。每次狀態重繪只會執行一次算繪，用 <code>jq</code> 解析以管線傳入的 JSON，視需要再 <code>grep</code> 紀錄檔的最新一行，然後印出。即使開啟耗時追蹤，典型算繪也在 ≤ 50 毫秒以內。',
    'faq.q.jq': '沒有 jq 也能用嗎？',
    'faq.a.jq': '一定要 <code>jq</code> — 它負責解析 Claude Code 透過 stdin 送來的 JSON。可透過 <code>brew install jq</code>（macOS）、<code>apt install jq</code>（Debian/Ubuntu）或 <code>choco install jq</code>（Windows）安裝。',
    'faq.q.win': '它在 Windows 上能用嗎？',
    'faq.a.win': '可以，只要環境能執行 <code>bash</code> 4+ 與 <code>jq</code> 即可 — Git Bash、WSL、MSYS2、Cygwin。純 CMD/PowerShell 不支援。',
    'faq.q.conf': '設定存放在哪裡？',
    'faq.a.conf': '<code>~/.claude/statusline.conf</code> — 一個由套件 CLI（<code>statusline.sh use &lt;theme&gt;</code> 等）寫入、以 shell 載入的小檔案。會在重新啟動後保留。',
    'faq.q.free': '它是免費的嗎？我可以商業使用嗎？',
    'faq.a.free': '個人本機使用免費 — 詳見<a href="https://github.com/OWNER/claude-code-statusline/blob/main/LICENSE">原始碼可取得授權</a>。任何再利用、再散布、fork 或納入其他專案，都須取得作者的<strong>事先書面許可</strong>。針對個人、教育與非商業用途的合理請求通常都會獲准。',
    'faq.q.time': '人工工時追蹤是怎麼運作的？',
    'faq.a.time': '<strong>time</strong> 佈景主題會讀取 JSONL 紀錄檔的時間戳記，並回報兩種時長：<strong>active</strong>（所有短於 5 分鐘的訊息間隔之總和）與 <strong>wall</strong>（從第一則到最後一則訊息的整段跨度）。5 分鐘的閒置門檻可自訂。',
    'faq.q.revert': '我要怎麼還原成預設的 Claude Code 狀態列？',
    'faq.a.revert': '可以從 <code>~/.claude/settings.json</code> 移除 <code>statusLine</code> 區塊，或執行 <code>~/.claude/status-line.sh reset</code> 並切換到與預設高度相近的 <code>minimal</code> 佈景主題。',
    'faq.q.reset': '5h{1.1h}: 1% 是什麼意思？',
    'faq.a.reset': '你已用掉 5 小時視窗的 1%，而 <code>{1.1h}</code> 是即時倒數 — 該視窗會在 1.1 小時後重置（<code>7d{1.1d}</code>：每週視窗會在 1.1 天後重置）。每次算繪都會從 <code>rate_limits.*.resets_at</code> 讀取。你的版本沒有重置時間戳記嗎？量表會退回顯示單純的 <code>5h: 1%</code>。',

