    'install.sub': 'Zaczynamy',
    'vibe.eyebrow': 'Instalacja na luzie',
    'vibe.title': 'Po co dotykać terminala,<br/>gdy masz <em>Claude Code</em>?',
    'vibe.intro': 'Wklej ten jeden prompt do swojej sesji Claude Code. Powiedz „y”, gdy poprosi o pozwolenie. Gotowe.',
    'vibe.bonus': 'Żadnego git, żadnych tańców z instalacją jq, żadnego szukania <code class="mono">settings.json</code> — Claude obsługuje każdy krok i pyta przed każdą komendą.',
    'vibe.panel.label': 'wklej w Claude Code:',
    'vibe.prompt': 'Install claude-code-statusline by amazopic for me. First make sure jq is installed (run `which jq`) — if missing, install it for the platform: `sudo apt-get install -y jq` (Ubuntu/Debian), `sudo dnf install -y jq` (Fedora), `brew install jq` (macOS), `sudo apk add jq` (Alpine). Then read ~/.claude/settings.json — if it has a statusLine.command pointing to an existing file (e.g. ~/.claude/status-line.sh or another path), back up that file by appending .bak (overwrite any existing .bak). Also if ~/.claude/status-line.sh already exists, back it up the same way. Then clone github.com/amazopic/claude-code-statusline, copy statusline-bundle.sh to ~/.claude/status-line.sh and make it executable, also copy commands/statusline.md to ~/.claude/commands/. Update ~/.claude/settings.json so statusLine is { type: "command", command: "<absolute path to ~/.claude/status-line.sh>" }. Finally run ~/.claude/status-line.sh use developer to test the developer theme and tell me to restart Claude Code.',
    'vibe.note': '↳ Po prostu mów <code class="mono">y</code> (tak) przy każdej prośbie o pozwolenie — Claude wykona każdą komendę po kolei.',
    'install.title': 'Zainstaluj w 30 sekund',
    'install.intro': 'Jeden spakowany skrypt robi obie rzeczy: renderuje twój pasek stanu, gdy Claude Code go wywołuje, i działa jako konfigurator CLI, gdy wywołasz go z argumentami.',
    'install.step1.title': 'Sklonuj i skopiuj',
    'install.step1.desc': 'Wrzuć bundle do <code class="mono">~/.claude/status-line.sh</code>.',
    'install.step2.title': 'Wybierz motyw',
    'install.step2.desc': 'Albo skomponuj bloki przez <code class="mono">custom</code>.',
    'install.step3.title': 'Podłącz',
    'install.step3.desc': 'Powiedz o tym Claude Code w <code class="mono">settings.json</code>, zrestartuj.',
    'install.claude.label': 'Albo w Claude Code — najłatwiej',
    'install.claude.intro': 'Masz otwarty Claude Code? Wklej te dwa prompty i gotowe — bez terminala.',
    'install.claude.prompt1': 'Install claude-code-statusline by amazopic for me. First make sure jq is installed (run `which jq`) — if missing, install it for the platform: `sudo apt-get install -y jq` (Ubuntu/Debian), `sudo dnf install -y jq` (Fedora), `brew install jq` (macOS), `sudo apk add jq` (Alpine). Then read ~/.claude/settings.json — if it has a statusLine.command pointing to an existing file (e.g. ~/.claude/status-line.sh or another path), back up that file by appending .bak (overwrite any existing .bak). Also if ~/.claude/status-line.sh already exists, back it up the same way. Then clone github.com/amazopic/claude-code-statusline, copy statusline-bundle.sh to ~/.claude/status-line.sh and make it executable, also copy commands/statusline.md to ~/.claude/commands/. Update ~/.claude/settings.json so statusLine is { type: "command", command: "<absolute path to ~/.claude/status-line.sh>" }. Finally run ~/.claude/status-line.sh use developer to test the developer theme and tell me to restart Claude Code.',
    'install.claude.prompt2_label': 'Następnie przetestuj:',
    'install.codelabel.main': 'macOS / Linux / WSL',
    'install.codelabel.slash': 'Opcjonalnie: komenda slash <code class="mono">/statusline</code>',

    'faq.sub': 'P &amp; O',
    'faq.title': 'Często<br/>zadawane',
    'faq.q.limits': 'Dlaczego wyświetlanie limitów 5h / 7d to funkcja flagowa?',
    'faq.a.limits': 'Bo to rzecz #1, na którą narzekają użytkownicy po kupnie planu Claude: domyślny pasek stanu Claude Code daje ci <strong>zerową widoczność</strong> twoich limitów 5-godzinnych i 7-dniowych. Dowiadujesz się, że je przekroczyłeś, dopiero gdy Claude odmawia odpowiedzi w połowie zadania. Ten skrypt czyta dane <code>limits</code> z żywego JSON-a, renderuje oba liczniki w czasie rzeczywistym i uruchamia ⚠️ alert wizualny, gdy przekroczysz 50 % — więc możesz zaplanować sesję, zanim rozbijesz się o ścianę.',
    'faq.q.what': 'Czym jest „Claude Code Status Line”?',
    'faq.a.what': 'Oparty na bashu zamiennik domyślnego paska stanu w <a href="https://claude.com/claude-code">Claude Code</a> (CLI od Anthropic). Zamienia linię u dołu ekranu w prawdziwy panel: model, % kontekstu, pasek postępu, koszt sesji, <strong>limity 5h / 7d</strong>, status git, czas zadania i więcej.',
